# the shapes that used to slip past the old character-based sizing
SAMPLE_BODIES = [
    '{"attributeId":"223549","title":"Pillowcase Included"},' * 4000,
    "\u00fcber OEKO-TEX\u00ae certified " * 4000,
    "x" * 200000,
    "",
