# the private span._parent walk in SafeTracer.local_span_chain() is the thing a
# ddtrace bump can silently break, so pin its behavior here. see logutil.py.


def test_no_emitted_line_crosses_the_log_driver_cut(capsys):
    logger = getLogger("line-limit-test")
    logger.updateConfig(
        {"connection_id": "c" * 32, "function": "get_products", "org_name": "Luminous"}
    )
    for body in SAMPLE_BODIES:
        logger.info(body)
        for line in capsys.readouterr().out.splitlines():
            assert len(line.encode()) <= MAX_LINE_BYTES

